import re, json
try:
    hits=[]
    for m in re.finditer(r'Business Day', sub):
        hits.append(sub[max(0,m.start()-400):m.end()+150].replace("\n"," "))
    # print those containing a number word
    for h in hits:
        if re.search(r'(one|two|three|four|five|six|seven|eight|nine|ten|\d)\s*(\(.*?\))?\s*Business Day', h, re.I):
            print("===")
            print(h)
except Exception as e:
    print("ERR", e)
